-- Customer supplied references; no official ledger, no automatic approval.
CREATE TABLE monthly_baselines(
 id TEXT PRIMARY KEY, book_id TEXT NOT NULL, ledger_id TEXT NOT NULL, firm_id TEXT NOT NULL, company_id TEXT NOT NULL,
 kind TEXT NOT NULL CHECK(kind IN ('opening','closing')), version INTEGER NOT NULL CHECK(version>0), period TEXT NOT NULL,
 external_reference TEXT NOT NULL CHECK(length(trim(external_reference)) BETWEEN 1 AND 500), evidence_ref TEXT NOT NULL CHECK(length(trim(evidence_ref)) BETWEEN 1 AND 500), reason TEXT NOT NULL CHECK(length(trim(reason)) BETWEEN 3 AND 1000),
 original_format TEXT NOT NULL CHECK(original_format IN ('structured_entry','json','csv','legacy_snapshot','bridge_snapshot')),original_filename TEXT NOT NULL,original_content TEXT NOT NULL CHECK(length(original_content)>0),original_sha256 TEXT NOT NULL CHECK(length(original_sha256)=64),
 source_kind TEXT NOT NULL CHECK(source_kind IN ('manual','legacy_cutover','bridge_import')),source_id TEXT,lines_json TEXT NOT NULL,
 created_by TEXT NOT NULL REFERENCES users(id), created_at TEXT NOT NULL,request_key TEXT NOT NULL,request_fingerprint TEXT NOT NULL CHECK(length(request_fingerprint)=64),
 CHECK((source_kind='manual' AND source_id IS NULL) OR (source_kind<>'manual' AND source_id IS NOT NULL)),
 UNIQUE(book_id,kind,version),UNIQUE(id,book_id,firm_id,company_id),UNIQUE(firm_id,created_by,request_key),
 FOREIGN KEY(book_id,firm_id,company_id) REFERENCES books(id,firm_id,company_id),FOREIGN KEY(ledger_id,firm_id,company_id) REFERENCES ledgers(id,firm_id,company_id)
);
CREATE TABLE monthly_baseline_confirmations(
 baseline_id TEXT PRIMARY KEY,book_id TEXT NOT NULL,firm_id TEXT NOT NULL,company_id TEXT NOT NULL,confirmed_by TEXT NOT NULL REFERENCES users(id),reason TEXT NOT NULL CHECK(length(trim(reason)) BETWEEN 3 AND 1000),created_at TEXT NOT NULL,
 FOREIGN KEY(baseline_id,book_id,firm_id,company_id) REFERENCES monthly_baselines(id,book_id,firm_id,company_id)
);
CREATE TABLE monthly_checks(
 id TEXT PRIMARY KEY,book_id TEXT NOT NULL,ledger_id TEXT NOT NULL,firm_id TEXT NOT NULL,company_id TEXT NOT NULL,version INTEGER NOT NULL CHECK(version>0),opening_id TEXT NOT NULL,closing_id TEXT NOT NULL,inputs_json TEXT NOT NULL,report_json TEXT NOT NULL,input_fingerprint TEXT NOT NULL CHECK(length(input_fingerprint)=64),created_by TEXT NOT NULL REFERENCES users(id),created_at TEXT NOT NULL,request_key TEXT NOT NULL,request_fingerprint TEXT NOT NULL CHECK(length(request_fingerprint)=64),
 UNIQUE(book_id,version),UNIQUE(id,book_id,firm_id,company_id),UNIQUE(firm_id,created_by,request_key),
 FOREIGN KEY(book_id,firm_id,company_id) REFERENCES books(id,firm_id,company_id),FOREIGN KEY(ledger_id,firm_id,company_id) REFERENCES ledgers(id,firm_id,company_id),
 FOREIGN KEY(opening_id,book_id,firm_id,company_id) REFERENCES monthly_baselines(id,book_id,firm_id,company_id),FOREIGN KEY(closing_id,book_id,firm_id,company_id) REFERENCES monthly_baselines(id,book_id,firm_id,company_id)
);
CREATE TABLE monthly_check_closures(
 check_id TEXT PRIMARY KEY,book_id TEXT NOT NULL,firm_id TEXT NOT NULL,company_id TEXT NOT NULL,closed_by TEXT NOT NULL REFERENCES users(id),reason TEXT NOT NULL CHECK(length(trim(reason)) BETWEEN 3 AND 1000),created_at TEXT NOT NULL,
 FOREIGN KEY(check_id,book_id,firm_id,company_id) REFERENCES monthly_checks(id,book_id,firm_id,company_id)
);
CREATE TABLE recurring_plan_versions(
 plan_id TEXT NOT NULL,version INTEGER NOT NULL CHECK(version>0),ledger_id TEXT NOT NULL,book_id TEXT NOT NULL,firm_id TEXT NOT NULL,company_id TEXT NOT NULL,
 name TEXT NOT NULL CHECK(length(trim(name)) BETWEEN 1 AND 120),start_period TEXT NOT NULL,end_period TEXT,day INTEGER NOT NULL CHECK(day BETWEEN 1 AND 28),description TEXT NOT NULL CHECK(length(trim(description)) BETWEEN 1 AND 500),evidence_ref TEXT NOT NULL CHECK(length(trim(evidence_ref)) BETWEEN 1 AND 500),reason TEXT NOT NULL CHECK(length(trim(reason)) BETWEEN 3 AND 1000),lines_json TEXT NOT NULL,catalog_json TEXT NOT NULL,created_by TEXT NOT NULL REFERENCES users(id),created_at TEXT NOT NULL,request_key TEXT NOT NULL,request_fingerprint TEXT NOT NULL CHECK(length(request_fingerprint)=64),
 PRIMARY KEY(plan_id,version),UNIQUE(plan_id,version,ledger_id,firm_id,company_id),UNIQUE(firm_id,created_by,request_key),
 CHECK(end_period IS NULL OR end_period>=start_period),FOREIGN KEY(book_id,firm_id,company_id) REFERENCES books(id,firm_id,company_id),FOREIGN KEY(ledger_id,firm_id,company_id) REFERENCES ledgers(id,firm_id,company_id)
);
CREATE TABLE recurring_plan_approvals(
 plan_id TEXT NOT NULL,version INTEGER NOT NULL,ledger_id TEXT NOT NULL,book_id TEXT NOT NULL,firm_id TEXT NOT NULL,company_id TEXT NOT NULL,approved_by TEXT NOT NULL REFERENCES users(id),reason TEXT NOT NULL CHECK(length(trim(reason)) BETWEEN 3 AND 1000),created_at TEXT NOT NULL,
 PRIMARY KEY(plan_id,version),FOREIGN KEY(plan_id,version,ledger_id,firm_id,company_id) REFERENCES recurring_plan_versions(plan_id,version,ledger_id,firm_id,company_id),FOREIGN KEY(book_id,firm_id,company_id) REFERENCES books(id,firm_id,company_id)
);
CREATE TABLE recurring_generations(
 plan_id TEXT NOT NULL,version INTEGER NOT NULL,ledger_id TEXT NOT NULL,book_id TEXT NOT NULL,firm_id TEXT NOT NULL,company_id TEXT NOT NULL,period TEXT NOT NULL,source_id TEXT NOT NULL UNIQUE,draft_id TEXT NOT NULL UNIQUE,created_by TEXT NOT NULL REFERENCES users(id),created_at TEXT NOT NULL,request_key TEXT NOT NULL,request_fingerprint TEXT NOT NULL CHECK(length(request_fingerprint)=64),
 PRIMARY KEY(plan_id,book_id),UNIQUE(plan_id,ledger_id,period),UNIQUE(firm_id,created_by,request_key),FOREIGN KEY(plan_id,version,ledger_id,firm_id,company_id) REFERENCES recurring_plan_versions(plan_id,version,ledger_id,firm_id,company_id),FOREIGN KEY(book_id,firm_id,company_id) REFERENCES books(id,firm_id,company_id),FOREIGN KEY(source_id,book_id) REFERENCES sources(id,book_id),FOREIGN KEY(draft_id,source_id,book_id) REFERENCES drafts(id,source_id,book_id)
);
CREATE INDEX idx_monthly_baselines_book ON monthly_baselines(book_id,kind,version DESC);
CREATE INDEX idx_monthly_checks_book ON monthly_checks(book_id,version DESC);
CREATE INDEX idx_recurring_plan_ledger ON recurring_plan_versions(ledger_id,plan_id,version DESC);

CREATE TRIGGER monthly_baselines_open_scope BEFORE INSERT ON monthly_baselines
 WHEN NOT EXISTS(SELECT 1 FROM books b JOIN ledger_periods l ON l.book_id=b.id JOIN periods p ON p.book_id=b.id AND p.period=b.period WHERE b.id=NEW.book_id AND b.firm_id=NEW.firm_id AND b.company_id=NEW.company_id AND p.status='open')
 BEGIN SELECT RAISE(ABORT,'Open same-company period required');END;
 CREATE TRIGGER monthly_baselines_immutable_update BEFORE UPDATE ON monthly_baselines BEGIN SELECT RAISE(ABORT,'Monthly evidence is immutable');END;
 CREATE TRIGGER monthly_baselines_immutable_delete BEFORE DELETE ON monthly_baselines BEGIN SELECT RAISE(ABORT,'Monthly evidence is immutable');END;

CREATE TRIGGER monthly_baselines_ledger_scope BEFORE INSERT ON monthly_baselines WHEN NOT EXISTS(SELECT 1 FROM ledger_periods WHERE book_id=NEW.book_id AND ledger_id=NEW.ledger_id AND firm_id=NEW.firm_id AND company_id=NEW.company_id) BEGIN SELECT RAISE(ABORT,'Wrong long-term ledger');END;
