CREATE TRIGGER monthly_baseline_facts BEFORE INSERT ON monthly_baselines
 WHEN NOT json_valid(NEW.lines_json) OR json_type(NEW.lines_json)<>'array' OR json_array_length(NEW.lines_json) NOT BETWEEN 1 AND 1000
 OR NEW.period<>(SELECT CASE WHEN NEW.kind='opening' THEN strftime('%Y-%m',b.period||'-01','-1 month') ELSE b.period END FROM books b WHERE b.id=NEW.book_id)
 OR NEW.version<>(SELECT coalesce(max(version),0)+1 FROM monthly_baselines WHERE book_id=NEW.book_id AND kind=NEW.kind)
 OR EXISTS(SELECT 1 FROM json_each(NEW.lines_json) x WHERE json_type(x.value,'$.balance_cents') IS NOT 'integer' OR abs(json_extract(x.value,'$.balance_cents'))>99999999999999 OR json_type(x.value,'$.auxiliary_values') IS NOT 'object' OR NOT EXISTS(SELECT 1 FROM accounts a WHERE a.book_id=NEW.book_id AND a.code=json_extract(x.value,'$.account_code') AND a.active=1))
 OR (SELECT count(*) FROM json_each(NEW.lines_json))<>(SELECT count(DISTINCT json_extract(x.value,'$.account_code')||':'||json_extract(x.value,'$.auxiliary_values')) FROM json_each(NEW.lines_json) x)
 BEGIN SELECT RAISE(ABORT,'Valid exact baseline dimensions and version required');END;

CREATE TRIGGER monthly_baseline_review BEFORE INSERT ON monthly_baseline_confirmations WHEN NOT EXISTS(SELECT 1 FROM monthly_baselines b WHERE b.id=NEW.baseline_id AND b.book_id=NEW.book_id AND b.created_by<>NEW.confirmed_by AND b.version=(SELECT max(version) FROM monthly_baselines WHERE book_id=b.book_id AND kind=b.kind)) BEGIN SELECT RAISE(ABORT,'Independent latest baseline review required');END;
CREATE TRIGGER monthly_check_scope BEFORE INSERT ON monthly_checks WHEN NOT EXISTS(SELECT 1 FROM monthly_baselines b JOIN monthly_baseline_confirmations c ON c.baseline_id=b.id WHERE b.id=NEW.opening_id AND b.book_id=NEW.book_id AND b.kind='opening' AND b.version=(SELECT max(version) FROM monthly_baselines WHERE book_id=b.book_id AND kind=b.kind)) OR NOT EXISTS(SELECT 1 FROM monthly_baselines b JOIN monthly_baseline_confirmations c ON c.baseline_id=b.id WHERE b.id=NEW.closing_id AND b.book_id=NEW.book_id AND b.kind='closing' AND b.version=(SELECT max(version) FROM monthly_baselines WHERE book_id=b.book_id AND kind=b.kind)) OR NEW.version<>(SELECT coalesce(max(version),0)+1 FROM monthly_checks WHERE book_id=NEW.book_id) OR json_extract(NEW.inputs_json,'$.period') IS NOT (SELECT period FROM books WHERE id=NEW.book_id) OR json_extract(NEW.inputs_json,'$.book_id') IS NOT NEW.book_id OR json_extract(NEW.inputs_json,'$.opening_id') IS NOT NEW.opening_id OR json_extract(NEW.inputs_json,'$.closing_id') IS NOT NEW.closing_id OR json_extract(NEW.report_json,'$.official_report') IS NOT 0 OR json_extract(NEW.report_json,'$.input_fingerprint') IS NOT NEW.input_fingerprint BEGIN SELECT RAISE(ABORT,'Scoped confirmed references required');END;
CREATE TRIGGER recurring_plan_facts BEFORE INSERT ON recurring_plan_versions
 WHEN NEW.version<>(SELECT coalesce(max(version),0)+1 FROM recurring_plan_versions WHERE plan_id=NEW.plan_id)
 OR EXISTS(SELECT 1 FROM recurring_plan_versions WHERE plan_id=NEW.plan_id AND (ledger_id<>NEW.ledger_id OR firm_id<>NEW.firm_id OR company_id<>NEW.company_id))
 OR NOT json_valid(NEW.lines_json) OR json_type(NEW.lines_json)<>'array' OR json_array_length(NEW.lines_json) NOT BETWEEN 2 AND 100
 OR EXISTS(SELECT 1 FROM json_each(NEW.lines_json) x WHERE json_type(x.value,'$.debit_cents') IS NOT 'integer' OR json_type(x.value,'$.credit_cents') IS NOT 'integer' OR json_extract(x.value,'$.debit_cents')<0 OR json_extract(x.value,'$.credit_cents')<0 OR (json_extract(x.value,'$.debit_cents')>0)=(json_extract(x.value,'$.credit_cents')>0) OR json_type(x.value,'$.auxiliary_values') IS NOT 'object' OR NOT EXISTS(SELECT 1 FROM accounts a WHERE a.book_id=NEW.book_id AND a.code=json_extract(x.value,'$.account_code') AND a.active=1))
 OR (SELECT sum(json_extract(value,'$.debit_cents')) FROM json_each(NEW.lines_json)) NOT BETWEEN 1 AND 99999999999999
 OR (SELECT sum(json_extract(value,'$.debit_cents')) FROM json_each(NEW.lines_json))<>(SELECT sum(json_extract(value,'$.credit_cents')) FROM json_each(NEW.lines_json))
 BEGIN SELECT RAISE(ABORT,'Explicit exact balanced recurring plan required');END;
CREATE TRIGGER recurring_plan_review BEFORE INSERT ON recurring_plan_approvals WHEN NOT EXISTS(SELECT 1 FROM recurring_plan_versions p WHERE p.plan_id=NEW.plan_id AND p.version=NEW.version AND p.created_by<>NEW.approved_by AND p.version=(SELECT max(version) FROM recurring_plan_versions WHERE plan_id=p.plan_id)) BEGIN SELECT RAISE(ABORT,'Independent current recurring plan approval required');END;
CREATE TRIGGER recurring_generation_facts BEFORE INSERT ON recurring_generations
 WHEN NOT EXISTS(SELECT 1 FROM recurring_plan_versions p JOIN recurring_plan_approvals a ON a.plan_id=p.plan_id AND a.version=p.version JOIN books b ON b.id=NEW.book_id JOIN sources s ON s.id=NEW.source_id AND s.book_id=b.id JOIN drafts d ON d.id=NEW.draft_id AND d.source_id=s.id AND d.book_id=b.id WHERE p.plan_id=NEW.plan_id AND p.version=NEW.version AND p.version=(SELECT max(version) FROM recurring_plan_versions WHERE plan_id=p.plan_id) AND p.ledger_id=NEW.ledger_id AND NEW.period=b.period AND b.period>=p.start_period AND (p.end_period IS NULL OR b.period<=p.end_period) AND d.status='draft' AND d.version=1 AND s.source_kind='business' AND s.external_id='monthly:'||p.plan_id||':'||NEW.period AND s.description=p.description AND d.description=p.description AND s.evidence_ref=p.evidence_ref AND s.date=NEW.period||'-'||printf('%02d',p.day) AND s.amount_cents=(SELECT sum(json_extract(value,'$.debit_cents')) FROM json_each(p.lines_json)))
 OR (SELECT count(*) FROM draft_lines WHERE draft_id=NEW.draft_id AND book_id=NEW.book_id)<>(SELECT json_array_length(lines_json) FROM recurring_plan_versions WHERE plan_id=NEW.plan_id AND version=NEW.version)
 OR EXISTS(SELECT 1 FROM recurring_plan_versions p,json_each(p.lines_json) x WHERE p.plan_id=NEW.plan_id AND p.version=NEW.version AND NOT EXISTS(SELECT 1 FROM draft_lines l LEFT JOIN draft_line_auxiliaries a ON a.draft_id=l.draft_id AND a.ordinal=l.ordinal WHERE l.draft_id=NEW.draft_id AND l.book_id=NEW.book_id AND l.ordinal=x.key AND l.account_code=json_extract(x.value,'$.account_code') AND l.debit_cents=json_extract(x.value,'$.debit_cents') AND l.credit_cents=json_extract(x.value,'$.credit_cents') AND (SELECT count(*) FROM json_each(coalesce(a.values_json,'{}')))=(SELECT count(*) FROM json_each(json_extract(x.value,'$.auxiliary_values'))) AND NOT EXISTS(SELECT 1 FROM json_each(json_extract(x.value,'$.auxiliary_values')) kv WHERE json_extract(coalesce(a.values_json,'{}'),'$.'||kv.key) IS NOT kv.value)))
 BEGIN SELECT RAISE(ABORT,'Exact unreviewed generated draft required');END;

CREATE VIEW closing_fact_basis_stage16 AS SELECT b.id AS book_id,json_object('books',json((SELECT COALESCE(json_group_array(json(record)),'[]') FROM (SELECT json_object('id',t.id,'firm_id',t.firm_id,'company_id',t.company_id,'name',t.name,'period',t.period) AS record FROM books t WHERE t.id=b.id ORDER BY t.id,t.firm_id,t.company_id))),'periods',json((SELECT COALESCE(json_group_array(json(record)),'[]') FROM (SELECT json_object('book_id',t.book_id,'period',t.period,'status',t.status) AS record FROM periods t WHERE t.book_id=b.id ORDER BY t.book_id,t.period,t.status))),'sources',json((SELECT COALESCE(json_group_array(json(record)),'[]') FROM (SELECT json_object('id',t.id,'book_id',t.book_id,'external_id',t.external_id,'source_name',t.source_name,'date',t.date,'description',t.description,'counterparty',t.counterparty,'amount_cents',t.amount_cents,'direction',t.direction,'evidence_ref',t.evidence_ref,'fingerprint',t.fingerprint,'source_kind',t.source_kind) AS record FROM sources t WHERE t.book_id=b.id ORDER BY t.id,t.book_id,t.external_id))),'drafts',json((SELECT COALESCE(json_group_array(json(record)),'[]') FROM (SELECT json_object('id',t.id,'book_id',t.book_id,'source_id',t.source_id,'description',t.description,'status',t.status,'version',t.version,'explanation',t.explanation,'approved_by',t.approved_by,'approved_at',t.approved_at,'exported_at',t.exported_at,'last_manual_edit_version',t.last_manual_edit_version) AS record FROM drafts t WHERE t.book_id=b.id ORDER BY t.id,t.book_id,t.source_id))),'draft_lines',json((SELECT COALESCE(json_group_array(json(record)),'[]') FROM (SELECT json_object('draft_id',t.draft_id,'book_id',t.book_id,'ordinal',t.ordinal,'account_code',t.account_code,'debit_cents',t.debit_cents,'credit_cents',t.credit_cents) AS record FROM draft_lines t WHERE t.book_id=b.id ORDER BY t.draft_id,t.book_id,t.ordinal))),'draft_line_auxiliaries',json((SELECT COALESCE(json_group_array(json(record)),'[]') FROM (SELECT json_object('draft_id',t.draft_id,'book_id',t.book_id,'ordinal',t.ordinal,'values_json',t.values_json) AS record FROM draft_line_auxiliaries t WHERE t.book_id=b.id ORDER BY t.draft_id,t.book_id,t.ordinal))),'accounts',json((SELECT COALESCE(json_group_array(json(record)),'[]') FROM (SELECT json_object('book_id',t.book_id,'code',t.code,'name',t.name,'active',t.active,'category',t.category,'normal_balance',t.normal_balance,'auxiliary_requirements',t.auxiliary_requirements,'version',t.version) AS record FROM accounts t WHERE t.book_id=b.id ORDER BY t.book_id,t.code,t.name))),'source_evidence',json((SELECT COALESCE(json_group_array(json(record)),'[]') FROM (SELECT json_object('id',t.id,'source_id',t.source_id,'book_id',t.book_id,'evidence_ref',t.evidence_ref,'created_at',t.created_at,'created_by',t.created_by) AS record FROM source_evidence t WHERE t.book_id=b.id ORDER BY t.id,t.source_id,t.book_id))),'business_mappings',json((SELECT COALESCE(json_group_array(json(record)),'[]') FROM (SELECT json_object('event_id',t.event_id,'firm_id',t.firm_id,'company_id',t.company_id,'book_id',t.book_id,'source_id',t.source_id,'draft_id',t.draft_id,'submitted_version',t.submitted_version,'idempotency_key',t.idempotency_key,'request_fingerprint',t.request_fingerprint,'created_by',t.created_by,'created_at',t.created_at) AS record FROM business_mappings t WHERE t.book_id=b.id ORDER BY t.event_id,t.firm_id,t.company_id))),'business_mapping_versions',json((SELECT COALESCE(json_group_array(json(record)),'[]') FROM (SELECT json_object('event_id',t.event_id,'firm_id',t.firm_id,'company_id',t.company_id,'book_id',t.book_id,'source_id',t.source_id,'draft_id',t.draft_id,'submitted_version',t.submitted_version,'idempotency_key',t.idempotency_key,'request_fingerprint',t.request_fingerprint,'created_by',t.created_by,'created_at',t.created_at) AS record FROM business_mapping_versions t WHERE t.book_id=b.id ORDER BY t.event_id,t.firm_id,t.company_id))),'business_events',json((SELECT COALESCE(json_group_array(json(record)),'[]') FROM (SELECT json_object('id',t.id,'firm_id',t.firm_id,'company_id',t.company_id,'department_id',t.department_id,'applicant_id',t.applicant_id,'template_id',t.template_id,'template_version',t.template_version,'version',t.version,'status',t.status,'payload',t.payload,'submitted_version',t.submitted_version,'created_at',t.created_at,'updated_at',t.updated_at,'create_key',t.create_key,'creation_fingerprint',t.creation_fingerprint,'fact_version',t.fact_version) AS record FROM business_events t WHERE t.firm_id=b.firm_id AND t.company_id=b.company_id AND (substr(json_extract(t.payload,'$.occurred_on'),1,7)=b.period OR (t.status<>'handed_off' AND NOT (COALESCE(length(json_extract(t.payload,'$.occurred_on'))=10 AND json_extract(t.payload,'$.occurred_on') GLOB '20[0-9][0-9]-[0-1][0-9]-[0-3][0-9]' AND strftime('%Y-%m-%d',json_extract(t.payload,'$.occurred_on'),'+0 days')=json_extract(t.payload,'$.occurred_on'),0)=1)) OR EXISTS(SELECT 1 FROM business_mapping_versions m WHERE m.event_id=t.id AND m.book_id=b.id)) ORDER BY t.id,t.firm_id,t.company_id))),'business_attachments',json((SELECT COALESCE(json_group_array(json(record)),'[]') FROM (SELECT json_object('id',t.id,'event_id',t.event_id,'firm_id',t.firm_id,'company_id',t.company_id,'storage_key',t.storage_key,'filename',t.filename,'media_type',t.media_type,'sha256',t.sha256,'size_bytes',t.size_bytes,'created_at',t.created_at,'created_by',t.created_by) AS record FROM business_attachments t WHERE t.event_id IN(SELECT e.id FROM business_events e WHERE e.firm_id=b.firm_id AND e.company_id=b.company_id AND (substr(json_extract(e.payload,'$.occurred_on'),1,7)=b.period OR (e.status<>'handed_off' AND NOT (COALESCE(length(json_extract(e.payload,'$.occurred_on'))=10 AND json_extract(e.payload,'$.occurred_on') GLOB '20[0-9][0-9]-[0-1][0-9]-[0-3][0-9]' AND strftime('%Y-%m-%d',json_extract(e.payload,'$.occurred_on'),'+0 days')=json_extract(e.payload,'$.occurred_on'),0)=1)) OR EXISTS(SELECT 1 FROM business_mapping_versions mv WHERE mv.event_id=e.id AND mv.book_id=b.id))) ORDER BY t.id,t.event_id,t.firm_id))),'case_tasks',json((SELECT COALESCE(json_group_array(json(record)),'[]') FROM (SELECT json_object('id',t.id,'firm_id',t.firm_id,'company_id',t.company_id,'event_id',t.event_id,'book_id',t.book_id,'source_id',t.source_id,'draft_id',t.draft_id,'kind',t.kind,'title',t.title,'request_reason',t.request_reason,'required_fields',t.required_fields,'attachment_required',t.attachment_required,'recipient_id',t.recipient_id,'assignee_id',t.assignee_id,'priority',t.priority,'due_on',t.due_on,'state',t.state,'version',t.version,'evidence_revision',t.evidence_revision,'accepted_fact_revision',t.accepted_fact_revision,'created_by',t.created_by,'created_at',t.created_at,'updated_at',t.updated_at) AS record FROM case_tasks t WHERE t.book_id=b.id OR t.event_id IN(SELECT e.id FROM business_events e WHERE e.firm_id=b.firm_id AND e.company_id=b.company_id AND (substr(json_extract(e.payload,'$.occurred_on'),1,7)=b.period OR (e.status<>'handed_off' AND NOT (COALESCE(length(json_extract(e.payload,'$.occurred_on'))=10 AND json_extract(e.payload,'$.occurred_on') GLOB '20[0-9][0-9]-[0-1][0-9]-[0-3][0-9]' AND strftime('%Y-%m-%d',json_extract(e.payload,'$.occurred_on'),'+0 days')=json_extract(e.payload,'$.occurred_on'),0)=1)) OR EXISTS(SELECT 1 FROM business_mapping_versions mv WHERE mv.event_id=e.id AND mv.book_id=b.id))) ORDER BY t.id,t.firm_id,t.company_id))),'case_responses',json((SELECT COALESCE(json_group_array(json(record)),'[]') FROM (SELECT json_object('id',t.id,'case_id',t.case_id,'firm_id',t.firm_id,'company_id',t.company_id,'state',t.state,'message',t.message,'fields',t.fields,'created_by',t.created_by,'created_at',t.created_at,'submitted_at',t.submitted_at,'reviewed_by',t.reviewed_by,'reviewed_at',t.reviewed_at,'review_reason',t.review_reason,'supersedes_attachment_ids',t.supersedes_attachment_ids) AS record FROM case_responses t WHERE t.case_id IN(SELECT c.id FROM case_tasks c WHERE c.book_id=b.id OR c.event_id IN(SELECT e.id FROM business_events e WHERE e.firm_id=b.firm_id AND e.company_id=b.company_id AND (substr(json_extract(e.payload,'$.occurred_on'),1,7)=b.period OR (e.status<>'handed_off' AND NOT (COALESCE(length(json_extract(e.payload,'$.occurred_on'))=10 AND json_extract(e.payload,'$.occurred_on') GLOB '20[0-9][0-9]-[0-1][0-9]-[0-3][0-9]' AND strftime('%Y-%m-%d',json_extract(e.payload,'$.occurred_on'),'+0 days')=json_extract(e.payload,'$.occurred_on'),0)=1)) OR EXISTS(SELECT 1 FROM business_mapping_versions mv WHERE mv.event_id=e.id AND mv.book_id=b.id)))) ORDER BY t.id,t.case_id,t.firm_id))),'case_supersessions',json((SELECT COALESCE(json_group_array(json(record)),'[]') FROM (SELECT json_object('old_attachment_id',t.old_attachment_id,'event_id',t.event_id,'case_id',t.case_id,'response_id',t.response_id,'firm_id',t.firm_id,'company_id',t.company_id,'accepted_by',t.accepted_by,'accepted_at',t.accepted_at) AS record FROM case_supersessions t WHERE t.event_id IN(SELECT e.id FROM business_events e WHERE e.firm_id=b.firm_id AND e.company_id=b.company_id AND (substr(json_extract(e.payload,'$.occurred_on'),1,7)=b.period OR (e.status<>'handed_off' AND NOT (COALESCE(length(json_extract(e.payload,'$.occurred_on'))=10 AND json_extract(e.payload,'$.occurred_on') GLOB '20[0-9][0-9]-[0-1][0-9]-[0-3][0-9]' AND strftime('%Y-%m-%d',json_extract(e.payload,'$.occurred_on'),'+0 days')=json_extract(e.payload,'$.occurred_on'),0)=1)) OR EXISTS(SELECT 1 FROM business_mapping_versions mv WHERE mv.event_id=e.id AND mv.book_id=b.id))) ORDER BY t.old_attachment_id,t.event_id,t.case_id))),'ocr_jobs',json((SELECT COALESCE(json_group_array(json(record)),'[]') FROM (SELECT json_object('id',t.id,'batch_id',t.batch_id,'firm_id',t.firm_id,'company_id',t.company_id,'event_id',t.event_id,'attachment_id',t.attachment_id,'expected_version',t.expected_version,'attachment_sha256',t.attachment_sha256,'configuration_fingerprint',t.configuration_fingerprint,'execution_user_id',t.execution_user_id,'created_by',t.created_by,'