='object' THEN json_extract(CASE WHEN json_valid(line.value) THEN line.value ELSE 'null' END,'$.auxiliary_values') ELSE '{}' END))=(SELECT count(*) FROM json_each(CASE WHEN json_type(CASE WHEN json_valid(wanted.value) THEN wanted.value ELSE 'null' END,'$.auxiliary_values')='object' THEN json_extract(CASE WHEN json_valid(wanted.value) THEN wanted.value ELSE 'null' END,'$.auxiliary_values') ELSE '{}' END)))
