      AND NOT EXISTS(SELECT 1 FROM json_each(CASE WHEN json_type(CASE WHEN json_valid(r.body_json) THEN r.body_json ELSE 'null' END,'$.items')='array' THEN json_extract(CASE WHEN json_valid(r.body_json) THEN r.body_json ELSE 'null' END,'$.items') ELSE '[]' END) i
        WHERE json_extract(CASE WHEN json_valid(i.value) THEN i.value ELSE 'null' END,'$.status') IS NULL OR json_extract(CASE WHEN json_valid(i.value) THEN i.value ELSE 'null' END,'$.status')<>'accepted' OR trim(COALESCE(json_extract(CASE WHEN json_valid(i.value) THEN i.value ELSE 'null' END,'$.external_voucher_id'),''))=''
        OR (SELECT count(*) FROM json_each(CASE WHEN json_type(CASE WHEN json_valid(r.body_json) THEN r.body_json ELSE 'null' END,'$.items')='array' THEN json_extract(CASE WHEN json_valid(r.body_json) THEN r.body_json ELSE 'null' END,'$.items') ELSE '[]' END) duplicate WHERE json_extract(CASE WHEN json_valid(duplicate.value) THEN duplicate.value ELSE 'null' END,'$.draft_id')=json_extract(CASE WHEN json_valid(i.value) THEN i.value ELSE 'null' END,'$.draft_id'))<>1
        OR (SELECT count(*) FROM json_each(CASE WHEN json_type(CASE WHEN json_valid(r.body_json) THEN r.body_json ELSE 'null' END,'$.items')='array' THEN json_extract(CASE WHEN json_valid(r.body_json) THEN r.body_json ELSE 'null' END,'$.items') ELSE '[]' END) duplicate WHERE json_extract(CASE WHEN json_valid(duplicate.value) THEN duplicate.value ELSE 'null' END,'$.external_voucher_id')=json_extract(CASE WHEN json_valid(i.value) THEN i.value ELSE 'null' END,'$.external_voucher_id'))<>1
        OR EXISTS(SELECT 1 FROM delivery_receipt_items h WHERE h.book_id=r.book_id AND h.receipt_id<>r.id AND
          (h.claimed_draft_id<>json_extract(CASE WHEN json_valid(i.value) THEN i.value ELSE 'null' END,'$.draft_id') AND h.external_voucher_id=json_extract(CASE WHEN json_valid(i.value) THEN i.value ELSE 'null' END,'$.external_voucher_id')
           OR h.claimed_draft_id=json_extract(CASE WHEN json_valid(i.value) THEN i.value ELSE 'null' END,'$.draft_id') AND trim(COALESCE(h.external_voucher_id,''))<>'' AND h.external_voucher_id<>json_extract(CASE WHEN json_valid(i.value) THEN i.value ELSE 'null' END,'$.external_voucher_id')))
        OR NOT EXISTS(SELECT 1 FROM json_each(CASE WHEN json_type(CASE WHEN json_valid(m.payload_json) THEN m.payload_json ELSE 'null' END,'$.items')='array' THEN json_extract(CASE WHEN json_valid(m.payload_json) THEN m.payload_json ELSE 'null' END,'$.items') ELSE '[]' END) expected WHERE json_extract(CASE WHEN json_valid(expected.value) THEN expected.value ELSE 'null' END,'$.draft_id')=json_extract(CASE WHEN json_valid(i.value) THEN i.value ELSE 'null' END,'$.draft_id') AND (json_extract(CASE WHEN json_valid(i.value) THEN i.value ELSE 'null' END,'$.date')) IS (json_extract(CASE WHEN json_valid(expected.value) THEN expected.value ELSE 'null' END,'$.date')) AND (json_extract(CASE WHEN json_valid(i.value) THEN i.value ELSE 'null' END,'$.amount')) IS (json_extract(CASE WHEN json_valid(expected.value) THEN expected.value ELSE 'null' END,'$.amount')) AND (json_extract(CASE WHEN json_valid(i.value) THEN i.value ELSE 'null' END,'$.description')) IS (json_extract(CASE WHEN json_valid(expected.value) THEN expected.value ELSE 'null' END,'$.description'))
          AND (SELECT count(*) FROM json_each(CASE WHEN json_type(CASE WHEN json_valid(i.value) THEN i.value ELSE 'null' END,'$.lines')='array' THEN json_extract(CASE WHEN json_valid(i.value) THEN i.value ELSE 'null' END,'$.lines') ELSE '[]' END) line)=(SELECT count(*) FROM json_each(CASE WHEN json_type(CASE WHEN json_valid(expected.value) THEN expected.value ELSE 'null' END,'$.lines')='array' THEN json_extract(CASE WHEN json_valid(expected.value) THEN expected.value ELSE 'null' END,'$.lines') ELSE '[]' END) wanted)
          AND (SELECT count(*) FROM json_each(CASE WHEN json_type(CASE WHEN json_valid(i.value) THEN i.value ELSE 'null' END,'$.lines')='array' THEN json_extract(CASE WHEN json_valid(i.value) THEN i.value ELSE 'null' END,'$.lines') ELSE '[]' END) line)>=2
          AND NOT EXISTS(SELECT 1 FROM json_each(CASE WHEN json_type(CASE WHEN json_valid(i.value) THEN i.value ELSE 'null' END,'$.lines')='array' THEN json_extract(CASE WHEN json_valid(i.value) THEN i.value ELSE 'null' END,'$.lines') ELSE '[]' END) line WHERE NOT EXISTS(SELECT 1 FROM json_each(CASE WHEN json_type(CASE WHEN json_valid(expected.value) THEN expected.value ELSE 'null' END,'$.lines')='array' THEN json_extract(CASE WHEN json_valid(expected.value) THEN expected.value ELSE 'null' END,'$.lines') ELSE '[]' END) wanted
            WHERE (json_extract(CASE WHEN json_valid(line.value) THEN line.value ELSE 'null' END,'$.ordinal')) IS (json_extract(CASE WHEN json_valid(wanted.value) THEN wanted.value ELSE 'null' END,'$.ordinal')) AND (json_extract(CASE WHEN json_valid(line.value) THEN line.value ELSE 'null' END,'$.account_code')) IS (json_extract(CASE WHEN json_valid(wanted.value) THEN wanted.value ELSE 'null' END,'$.account_code')) AND (json_extract(CASE WHEN json_valid(line.value) THEN line.value ELSE 'null' END,'$.debit')) IS (json_extract(CASE WHEN json_valid(wanted.value) THEN wanted.value ELSE 'null' END,'$.debit')) AND (json_extract(CASE WHEN json_valid(line.value) THEN line.value ELSE 'null' END,'$.credit')) IS (json_extract(CASE WHEN json_valid(wanted.value) THEN wanted.value ELSE 'null' END,'$.credit')) AND json_type(CASE WHEN json_valid(line.value) THEN line.value ELSE 'null' END,'$.auxiliary_values')='object' AND (json_extract(CASE WHEN json_valid(line.value) THEN line.value ELSE 'null' END,'$.auxiliary_values.department')) IS (json_extract(CASE WHEN json_valid(wanted.value) THEN wanted.value ELSE 'null' END,'$.auxiliary_values.department')) AND (json_extract(CASE WHEN json_valid(line.value) THEN line.value ELSE 'null' END,'$.auxiliary_values.employee')) IS (json_extract(CASE WHEN json_valid(wanted.value) THEN wanted.value ELSE 'null' END,'$.auxiliary_values.employee')) AND (json_extract(CASE WHEN json_valid(line.value) THEN line.value ELSE 'null' END,'$.auxiliary_values.counterparty')) IS (json_extract(CASE WHEN json_valid(wanted.value) THEN wanted.value ELSE 'null' END,'$.auxiliary_values.counterparty')) AND (json_extract(CASE WHEN json_valid(line.value) THEN line.value ELSE 'null' END,'$.auxiliary_values.project')) IS (json_extract(CASE WHEN json_valid(wanted.value) THEN wanted.value ELSE 'null' END,'$.auxiliary_values.project')) AND (SELECT count(*) FROM json_each(CASE WHEN json_type(CASE WHEN json_valid(line.value) THEN line.value ELSE 'null' END,'$.auxiliary_values')='object' THEN json_extract(CASE WHEN json_valid(line.value) THEN line.value ELSE 'null' END,'$.auxiliary_values') ELSE '{}' END))=(SELECT count(*) FROM json_each(CASE WHEN json_type(CASE WHEN json_valid(wanted.value) THEN wanted.value ELSE 'null' END,'$.auxiliary_values')='object' THEN json_extract(CASE WHEN json_valid(wanted.value) THEN wanted.value ELSE 'null' END,'$.auxiliary_values') ELSE '{}' END)))
            OR (SELECT count(*) FROM json_each(CASE WHEN json_type(CASE WHEN json_valid(i.value) THEN i.value ELSE 'null' END,'$.lines')='array' THEN json_extract(CASE WHEN json_valid(i.value) THEN i.value ELSE 'null' END,'$.lines') ELSE '[]' END) duplicate_line WHERE json_extract(CASE WHEN json_valid(duplicate_line.value) THEN duplicate_line.value ELSE 'null' END,'$.ordinal')=json_extract(CASE WHEN json_valid(line.value) THEN line.value ELSE 'null' END,'$.ordinal'))<>1)))
    )), verified_drafts AS(SELECT json_extract(i.value,'$.draft_id') AS draft_id FROM verified_exports x JOIN delivery_manifests m ON m.export_id=x.id JOIN json_each(m.payload_json,'$.items') i)
 SELECT d.book_id,d.id AS draft_id,d.version,d.status,l.ordinal,l.account_code,l.debit_cents,l.credit_cents,coalesce(a.values_json,'{}') AS auxiliary_values,
 CASE WHEN d.status='draft' THEN 'unreviewed' WHEN d.status='approved' THEN 'approved_pending_delivery' WHEN EXISTS(SELECT 1 FROM verified_drafts vd WHERE vd.draft_id=d.id) THEN 'verified_delivery' ELSE 'exported_pending_receipt' END AS group_name
 FROM drafts d JOIN sources s ON s.id=d.source_id AND s.book_id=d.book_id JOIN draft_lines l ON l.draft_id=d.id AND l.book_id=d.book_id LEFT JOIN draft_line_auxiliaries a ON a.draft_id=l.draft_id AND a.book_id=l.book_id AND a.ordinal=l.ordinal
 WHERE NOT EXISTS(SELECT 1 FROM fact_revision_lineage r WHERE r.old_book_id=s.book_id AND r.old_source_id=s.id) AND NOT EXISTS(SELECT 1 FROM bank_source_dispositions z WHERE z.book_id=s.book_id AND z.source_id=s.id) AND NOT EXISTS(SELECT 1 FROM ai_bank_links link WHERE link.bank_source_id=s.id AND link.book_id=s.book_id);
CREATE TRIGGER monthly_check_current BEFORE INSERT ON monthly_checks WHEN (SELECT count(*) FROM monthly_live_fact_rows WHERE book_id=NEW.book_id)<>(SELECT count(*) FROM json_each(NEW.inputs_json,'$.facts')) OR
 EXISTS(SELECT 1 FROM json_each(NEW.inputs_json,'$.facts') v WHERE NOT EXISTS(SELECT 1 FROM monthly_live_fact_rows l WHERE l.book_id=NEW.book_id AND l.draft_id=json_extract(v.value,'$.draft_id') AND l.version=json_extract(v.value,'$.version') AND l.status=json_extract(v.value,'$.status') AND l.ordinal=json_extract(v.value,'$.ordinal') AND l.account_code=json_extract(v.value,'$.account_code') AND l.debit_cents=json_extract(v.value,'$.debit_cents') AND l.credit_cents=json_extract(v.value,'$.credit_cents') AND l.group_name=json_extract(v.value,'$.group') AND (SELECT count(*) FROM json_each(l.auxiliary_values))=(SELECT count(*) FROM json_each(v.value,'$.auxiliary_values')) AND NOT EXISTS(SELECT 1 FROM json_each(v.value,'$.auxiliary_values') kv WHERE json_extract(l.auxiliary_values,'$.'||kv.key) IS NOT kv.value)))
