act(ln.value,'$.account_code') AND (json_extract(v.value,'$.auxiliary_values')=json_extract(ln.value,'$.auxiliary_values') OR json_extract(ln.value,'$.auxiliary_values')='{}' AND EXISTS(SELECT 1 FROM monthly_baselines b,json_each(b.lines_json) x WHERE b.id IN(NEW.opening_id,NEW.closing_id) AND json_extract(x.value,'$.account_code')=json_extract(ln.value,'$.account_code') AND json_extract(x.value,'$.auxiliary_values')='{}')) AND json_extract(v.value,'$.group')='verified_delivery')-(SELECT coalesce(sum(json_extract(v.value,'$.credit_cents')),0) FROM json_each(NEW.inputs_json,'$.facts') v WHERE json_extract(v.value,'$.account_code')=json_extract(ln.value,'$.account_code') AND (json_extract(v.value,'$.auxiliary_values')=json_extract(ln.value,'$.auxiliary_values') OR json_extract(ln.value,'$.auxiliary_values')='{}' AND EXISTS(SELECT 1 FROM monthly_baselines b,json_each(b.lines_json) x WHERE b.id IN(NEW.opening_id,NEW.closing_id) AND json_extract(x.value,'$.account_code')=json_extract(ln.value,'$.account_code') AND json_extract(x.value,'$.auxiliary_values')='{}')) AND json_extract(v.value,'$.group')='verified_delivery')))))/100 AS TEXT)||'.'||printf('%02d',abs(((SELECT json_extract(o.value,'$.balance_cents') FROM monthly_baselines b,json_each(b.lines_json) o WHERE b.id=NEW.closing_id AND json_extract(o.value,'$.account_code')=json_extract(ln.value,'$.account_code') AND json_extract(o.value,'$.auxiliary_values')=json_extract(ln.value,'$.auxiliary_values'))-((SELECT json_extract(o.value,'$.balance_cents') FROM monthly_baselines b,json_each(b.lines_json) o WHERE b.id=NEW.opening_id AND json_extract(o.value,'$.account_code')=json_extract(ln.value,'$.account_code') AND json_extract(o.value,'$.auxiliary_values')=json_extract(ln.value,'$.auxiliary_values'))+((SELECT coalesce(sum(json_extract(v.value,'$.debit_cents')),0) FROM json_each(NEW.inputs_json,'$.facts') v WHERE json_extract(v.value,'$.account_code')=json_extract(ln.value,'$.account_code') AND (json_extract(v.value,'$.auxiliary_values')=json_extract(ln.value,'$.auxiliary_values') OR json_extract(ln.value,'$.auxiliary_values')='{}' AND EXISTS(SELECT 1 FROM monthly_baselines b,json_each(b.lines_json) x WHERE b.id IN(NEW.opening_id,NEW.closing_id) AND json_extract(x.value,'$.account_code')=json_extract(ln.value,'$.account_code') AND json_extract(x.value,'$.auxiliary_values')='{}')) AND json_extract(v.value,'$.group')='verified_delivery')-(SELECT coalesce(sum(json_extract(v.value,'$.credit_cents')),0) FROM json_each(NEW.inputs_json,'$.facts') v WHERE json_extract(v.value,'$.account_code')=json_extract(ln.value,'$.account_code') AND (json_extract(v.value,'$.auxiliary_values')=json_extract(ln.value,'$.auxiliary_values') OR json_extract(ln.value,'$.auxiliary_values')='{}' AND EXISTS(SELECT 1 FROM monthly_baselines b,json_each(b.lines_json) x WHERE b.id IN(NEW.opening_id,NEW.closing_id) AND json_extract(x.value,'$.account_code')=json_extract(ln.value,'$.account_code') AND json_extract(x.value,'$.auxiliary_values')='{}')) AND json_extract(v.value,'$.group')='verified_delivery')))))%100) END)) BEGIN SELECT RAISE(ABORT,'Monthly reference amounts must match exact facts');END;
CREATE TRIGGER recurring_catalog_create BEFORE INSERT ON recurring_plan_versions WHEN NOT json_valid(NEW.catalog_json) OR json_type(NEW.catalog_json)<>'array'
 OR (SELECT count(*) FROM json_each(NEW.catalog_json))<>(SELECT count(DISTINCT json_extract(value,'$.account_code')) FROM json_each(NEW.lines_json))
 OR (SELECT count(*) FROM json_each(NEW.catalog_json))<>(SELECT count(DISTINCT json_extract(value,'$.code')) FROM json_each(NEW.catalog_json))
 OR EXISTS(SELECT 1 FROM json_each(NEW.catalog_json) v WHERE NOT EXISTS(SELECT 1 FROM accounts a WHERE a.book_id=NEW.book_id AND a.active=1 AND a.code=json_extract(v.value,'$.code') AND a.name=json_extract(v.value,'$.name') AND a.category=json_extract(v.value,'$.category') AND a.normal_balance=json_extract(v.value,'$.normal_balance') AND (SELECT count(*) FROM json_each(a.auxiliary_requirements))=(SELECT count(*) FROM json_each(v.value,'$.auxiliary_requirements')) AND NOT EXISTS(SELECT 1 FROM json_each(a.auxiliary_requirements) required WHERE NOT EXISTS(SELECT 1 FROM json_each(v.value,'$.auxiliary_requirements') x WHERE x.value=required.value)))) BEGIN SELECT RAISE(ABORT,'Actual company account catalog required');END;
CREATE TRIGGER recurring_plan_approvals_catalog BEFORE INSERT ON recurring_plan_approvals WHEN EXISTS(SELECT 1 FROM recurring_plan_versions p WHERE p.plan_id=NEW.plan_id AND p.version=NEW.version AND (NOT json_valid(p.catalog_json) OR json_type(p.catalog_json)<>'array'
 OR (SELECT count(*) FROM json_each(p.catalog_json))<>(SELECT count(DISTINCT json_extract(value,'$.account_code')) FROM json_each(p.lines_json))
 OR (SELECT count(*) FROM json_each(p.catalog_json))<>(SELECT count(DISTINCT json_extract(value,'$.code')) FROM json_each(p.catalog_json))
 OR EXISTS(SELECT 1 FROM json_each(p.catalog_json) v WHERE NOT EXISTS(SELECT 1 FROM accounts a WHERE a.book_id=NEW.book_id AND a.active=1 AND a.code=json_extract(v.value,'$.code') AND a.name=json_extract(v.value,'$.name') AND a.category=json_extract(v.value,'$.category') AND a.normal_balance=json_extract(v.value,'$.normal_balance') AND (SELECT count(*) FROM json_each(a.auxiliary_requirements))=(SELECT count(*) FROM json_each(v.value,'$.auxiliary_requirements')) AND NOT EXISTS(SELECT 1 FROM json_each(a.auxiliary_requirements) required WHERE NOT EXISTS(SELECT 1 FROM json_each(v.value,'$.auxiliary_requirements') x WHERE x.value=required.value)))))) BEGIN SELECT RAISE(ABORT,'Approved catalog drifted in current period');END;
CREATE TRIGGER recurring_generations_catalog BEFORE INSERT ON recurring_generations WHEN EXISTS(SELECT 1 FROM recurring_plan_versions p WHERE p.plan_id=NEW.plan_id AND p.version=NEW.version AND (NOT json_valid(p.catalog_json) OR json_type(p.catalog_json)<>'array'
 OR (SELECT count(*) FROM json_each(p.catalog_json))<>(SELECT count(DISTINCT json_extract(value,'$.account_code')) FROM json_each(p.lines_json))
 OR (SELECT count(*) FROM json_each(p.catalog_json))<>(SELECT count(DISTINCT json_extract(value,'$.code')) FROM json_each(p.catalog_json))
 OR EXISTS(SELECT 1 FROM json_each(p.catalog_json) v WHERE NOT EXISTS(SELECT 1 FROM accounts a WHERE a.book_id=NEW.book_id AND a.active=1 AND a.code=json_extract(v.value,'$.code') AND a.name=json_extract(v.value,'$.name') AND a.category=json_extract(v.value,'$.category') AND a.normal_balance=json_extract(v.value,'$.normal_balance') AND (SELECT count(*) FROM json_each(a.auxiliary_requirements))=(SELECT count(*) FROM json_each(v.value,'$.auxiliary_requirements')) AND NOT EXISTS(SELECT 1 FROM json_each(a.auxiliary_requirements) required WHERE NOT EXISTS(SELECT 1 FROM json_each(v.value,'$.auxiliary_requirements') x WHERE x.value=required.value)))))) BEGIN SELECT RAISE(ABORT,'Approved catalog drifted in current period');END;
CREATE TRIGGER monthly_check_line_set BEFORE INSERT ON monthly_checks WHEN
 json_type(NEW.report_json,'$.lines') IS NOT 'array' OR json_type(NEW.report_json,'$.unknown_count') IS NOT 'integer' OR json_type(NEW.report_json,'$.difference_count') IS NOT 'integer' OR json_extract(NEW.report_json,'$.currency') IS NOT 'CNY' OR json_extract(NEW.report_json,'$.coverage') IS NOT 'listed_dimensions_only'
 OR (SELECT count(*) FROM json_each(NEW.report_json,'$.lines'))<>(SELECT count(DISTINCT json_extract(v.value,'$.account_code')||':'||json_extract(v.value,'$.auxiliary_values')) FROM json_each(NEW.report_json,'$.lines') v)
 OR (SELECT count(*) FROM json_each(NEW.report_json,'$.lines'))<>(SELECT count(*) FROM(SELECT json_extract(value,'$.account_code'),json_extract(value,'$.auxiliary_values') FROM monthly_baselines b,json_each(b.lines_json) WHERE b.id=NEW.opening_id UNION SELECT json_extract(value,'$.account_code'),json_extract(value,'$.auxiliary_values') FROM monthly_baselines b,json_each(b.lines_json) WHERE b.id=NEW.closing_id UNION SELECT json_extract(value,'$.account_code'),json_extract(value,'$.auxiliary_values') FROM json_each(NEW.inputs_json,'$.facts')))
 OR EXISTS(SELECT 1 FROM json_each(NEW.report_json,'$.lines') ln WHERE NOT EXISTS(SELECT 1 FROM monthly_baselines b,json_each(b.lines_json) x WHERE b.id IN (NEW.opening_id,NEW.closing_id) AND json_extract(x.value,'$.account_code')=json_extract(ln.value,'$.account_code') AND json_extract(x.value,'$.auxiliary_values')=json_extract(ln.value,'$.auxiliary_values')) AND NOT EXISTS(SELECT 1 FROM json_each(NEW.inputs_json,'$.facts') x WHERE json_extract(x.value,'$.account_code')=json_extract(ln.value,'$.account_code') AND json_extract(x.value,'$.auxiliary_values')=json_extract(ln.value,'$.auxiliary_values')))
 OR json_extract(NEW.report_json,'$.difference_count') IS NOT (SELECT count(*) FROM json_each(NEW.report_json,'$.lines') WHERE json_extract(value,'$.difference') IS NOT NULL AND json_extract(value,'$.difference')<>'0.00')
 OR json_extract(NEW.report_json,'$.unknown_count') IS NOT (SELECT count(*) FROM json_each(NEW.report_json,'$.lines') WHERE json_extract(value,'$.difference') IS NULL)
 BEGIN SELECT RAISE(ABORT,'Complete exact monthly reference line set required');END;

CREATE VIEW monthly_check_currentness AS SELECT c.id AS check_id,c.book_id,CASE WHEN NOT((SELECT count(*) FROM monthly_live_fact_rows WHERE book_id=c.book_id)<>(SELECT count(*) FROM json_each(c.inputs_json,'$.facts')) OR
 EXISTS(SELECT 1 FROM json_each(c.inputs_json,'$.facts') v WHERE NOT EXISTS(SELECT 1 FROM monthly_live_fact_rows l WHERE l.book_id=c.book_id AND l.draft_id=json_extract(v.value,'$.draft_id') AND l.version=json_extract(v.value,'$.version') AND l.status=json_extract(v.value,'$.status') AND l.ordinal=json_extract(v.value,'$.ordinal') AND l.account_code=json_extract(v.value,'$.account_code') AND l.debit_cents=json_extract(v.value,'$.debit_cents') AND l.credit_cents=json_extract(v.value,'$.credit_cents') AND l.group_name=json_extract(v.value,'$.group') AND (SELECT count(*) FROM json_each(l.auxiliary_values))=(SELECT count(*) FROM json_each(v.value,'$.auxiliary_values')) AND NOT EXISTS(SELECT 1 FROM json_each(v.value,'$.auxiliary_values') kv WHERE json_extract(l.auxiliary_values,'$.'||kv.key) IS NOT kv.value)))
 OR (SELECT count(*) FROM json_each(c.inputs_json,'$.facts'))<>(SELECT count(DISTINCT json_extract(v.value,'$.draft_id')||':'||json_extract(v.value,'$.ordinal')) FROM json_each(c.inputs_json,'$.facts') v)
 OR (SELECT count(*) FROM delivery_receipts r WHERE r.book_id=c.book_id AND r.id=(SELECT r2.id FROM delivery_receipts r2 WHERE r2.export_id=r.export_id ORDER BY r2.created_at DESC,r2.id DESC LIMIT 1))<>(SELECT count(*) FROM json_each(c.inputs_json,'$.receipts'))
 OR EXISTS(SELECT 1 FROM json_each(c.inputs_json,'$.receipts') v WHERE NOT EXISTS(SELECT 1 FROM delivery_receipts r WHERE r.id=json_extract(v.value,'$.receipt_id') AND r.book_id=c.book_id AND r.export_id=json_extract(v.value,'$.export_id') AND r.request_fingerprint=json_extract(v.value,'$.body_hash') AND r.id=(SELECT r2.id FROM delivery_receipts r2 WHERE r2.export_id=r.export_id ORDER BY r2.created_at DESC,r2.id DESC LIMIT 1)))) AND NOT EXISTS(SELECT 1 FROM monthly_baselines n WHERE n.book_id=c.book_id AND ((n.kind='opening' AND n.version>(SELECT version FROM monthly_baselines WHERE id=c.opening_id)) OR (n.kind='closing' AND n.version>(SELECT version FROM monthly_baselines WHERE id=c.closing_id)))) THEN 1 ELSE 0 END AS is_current FROM monthly_checks c;
CREATE TRIGGER monthly_closure_current BEFORE INSERT ON monthly_check_closures WHEN NOT EXISTS(SELECT 1 FROM monthly_check_currentness n WHERE n.check_id=NEW.check_id AND n.book_id=NEW.book_id AND n.is_current=1) BEGIN SELECT RAISE(ABORT,'Cannot close stale monthly check');END;
